CREATE VIEW `active_tool_calls` AS select "tool_calls"."id", "tool_calls"."session_id", "sessions"."project_id", "tool_calls"."name", "tool_calls"."status", "tool_calls"."is_error", "tool_calls"."started_at", "tool_calls"."ended_at", "tool_calls"."duration_ms" from "tool_calls" inner join "events" on "tool_calls"."source_event_id" = "events"."id" inner join "sessions" on "tool_calls"."session_id" = "sessions"."id" where (("events"."is_usage_duplicate" = 0) and ("events"."is_dead_branch" = 0));--> statement-breakpoint
CREATE VIEW `active_usage_events` AS select "events"."id", "events"."session_id", "sessions"."project_id", "events"."timestamp_ms", "events"."model", "events"."input_tokens", "events"."output_tokens", "events"."cache_read_tokens", "events"."cache_write_tokens" from "events" inner join "sessions" on "events"."session_id" = "sessions"."id" where (("events"."has_usage" = 1) and ("events"."is_usage_duplicate" = 0) and ("events"."is_dead_branch" = 0));--> statement-breakpoint
CREATE VIEW `session_read_model` AS select "sessions"."id", "sessions"."source_session_id", "sessions"."project_id", "projects"."name", "projects"."path", "sessions"."parent_id", "sessions"."fork_of", "sessions"."agent_id", "sessions"."cwd", "sessions"."git_branch", "sessions"."claude_version", "session_stats"."user_turns", "session_stats"."assistant_turns", "session_stats"."tool_calls", "session_stats"."started_at", "session_stats"."ended_at", "session_stats"."duration_ms", "session_stats"."tok_input", "session_stats"."tok_output", "session_stats"."tok_cache_read", "session_stats"."tok_cache_write", "session_stats"."tok_dead_branch", "session_stats"."cost_usd", "session_stats"."updated_at" from "sessions" inner join "projects" on "sessions"."project_id" = "projects"."id" inner join "session_stats" on "sessions"."id" = "session_stats"."session_id";